package org.apache.commons.math3.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_31_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        ContinuedFraction cf = new ContinuedFraction() {
            @Override
            protected double getA(int n, double x) {
                return (n == 0) ? 1 : x / n;
            }

            @Override
            protected double getB(int n, double x) {
                return 1.0;
            }
        };

        double x = 1e-10;
        double epsilon = 1e-9;
        int maxIterations = 10000;

        try {
            double result = cf.evaluate(x, epsilon, maxIterations);
            // The expected result should be close to 1.0 for this continued fraction
            assertEquals(1.0, result, epsilon);
        } catch (Exception e) {
            fail("The evaluation should not throw an exception: " + e.getMessage());
        }
    }
}

